const recipes=[
{id:'cookie',name:'Chocolate chip cookies',level:'Very easy',color:'#eee8d5',desc:'Golden edges, gooey middles. A little hug in cookie form.',time:12,temp:175,mix:8,dry:[['Flour',4,'¼ cup'],['Sugar',2,'¼ cup'],['Baking soda',1,'¼ tsp'],['Chocolate chips',2,'¼ cup']],wet:[['Butter',2,'¼ cup'],['Egg',1,'egg'],['Vanilla',1,'tsp']],frost:'Chocolate',top:'Chocolate chips',customer:'Benny the bear',wish:'Chocolate drizzle and extra chocolate chips, please!'},
{id:'cupcake',name:'Vanilla cloud cupcakes',level:'Easy',color:'#f2dfe3',desc:'Fluffy little clouds with a swirl of pretty pink frosting.',time:18,temp:175,mix:10,dry:[['Flour',4,'¼ cup'],['Sugar',3,'¼ cup'],['Baking powder',2,'½ tsp'],['Salt',1,'pinch']],wet:[['Butter',2,'¼ cup'],['Egg',2,'egg'],['Milk',2,'¼ cup'],['Vanilla',1,'tsp']],frost:'Strawberry',top:'Sprinkles',customer:'Poppy the bunny',wish:'Pink strawberry frosting and rainbow sprinkles!'},
{id:'brownie',name:'Fudgy cocoa brownies',level:'Medium',color:'#dfebdf',desc:'Deep chocolate, crackly tops, and a wonderfully fudgy heart.',time:25,temp:170,mix:7,dry:[['Flour',3,'¼ cup'],['Sugar',4,'¼ cup'],['Cocoa',2,'¼ cup'],['Salt',1,'pinch']],wet:[['Butter',3,'¼ cup'],['Egg',2,'egg'],['Vanilla',1,'tsp']],frost:'Chocolate',top:'Strawberries',customer:'Mochi the cat',wish:'Chocolate on chocolate, with a few strawberries on top.'},
{id:'lemon',name:'Little lemon loaf',level:'Tricky',color:'#f5eccb',desc:'A sunny slice of lemon happiness, finished with a sweet glaze.',time:40,temp:170,mix:12,dry:[['Flour',6,'¼ cup'],['Sugar',4,'¼ cup'],['Baking powder',3,'½ tsp'],['Salt',1,'pinch']],wet:[['Butter',2,'¼ cup'],['Egg',3,'egg'],['Milk',2,'¼ cup'],['Lemon juice',2,'tbsp']],frost:'Lemon glaze',top:'Flowers',customer:'Clover the frog',wish:'A lemon glaze and edible flowers would make my day.'},
{id:'cake',name:'Strawberry dream cake',level:'Difficult',color:'#e7e0f1',desc:'A celebration in layers. Berries, buttercream, and a little magic.',time:30,temp:175,mix:15,dry:[['Flour',8,'¼ cup'],['Sugar',6,'¼ cup'],['Baking powder',4,'½ tsp'],['Salt',2,'pinch']],wet:[['Butter',4,'¼ cup'],['Egg',4,'egg'],['Milk',4,'¼ cup'],['Vanilla',2,'tsp']],frost:'Vanilla',top:'Strawberries',customer:'Rosie the fox',wish:'Vanilla buttercream with strawberries on top, please!'}];
const app=document.getElementById('app');let state=null,timer=null,mixTimer=null;const stages=['Dry ingredients','Wet ingredients','Mix','Bake','Decorate'];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function art(r,quality=1,frost=null){let inner='';const baked=quality<.35?'#715044':quality<.65?'#bd8b61':'#e4b67d',pink=frost===null?'#e4b67d':frost==='Chocolate'?'#775144':frost==='Lemon glaze'?'#f6e6a8':frost==='Vanilla'?'#fff6df':'#efb4c6';if(r.id==='cookie'){inner=[[-36,-20],[30,-27],[0,25]].map(([x,y])=>`<g transform="translate(${x} ${y})"><circle r="35" fill="${baked}" stroke="#b98759" stroke-width="3"/>${[[0,0],[-15,-14],[16,-9],[-10,18],[20,16]].map(([a,b])=>`<path d="M${a} ${b}l7 -2 3 8 -9 2z" fill="#785145"/>`).join('')}</g>`).join('')}else if(r.id==='cupcake'){inner=`<path d="M-44 5h88L33 66h-66z" fill="#dba9c0" stroke="#ab7d95" stroke-width="3"/><path d="M-23 12l7 46M0 12v47M23 12l-7 46" stroke="#f5d8e7" stroke-width="5"/><path d="M-47 7Q-61-11-34-22Q-44-43-13-44Q-16-65 5-66Q20-62 18-48Q52-44 38-24Q65-10 47 7Z" fill="${pink}" stroke="#c58c9e" stroke-width="3"/>`}else if(r.id==='brownie'){inner=`<path d="M-60-27L24-48 65-16 62 40-23 64-61 32Z" fill="#785045" stroke="#5c3c35" stroke-width="3"/><path d="M-60-27L24-48 65-16-22 10Z" fill="#ad7661"/><path d="M-47-22l20 8 14-14 18 9 20-15M-8-1l13-10 20 5 19-12" fill="none" stroke="#e0ad89" stroke-width="3"/>`}else if(r.id==='lemon'){inner=`<path d="M-66-20Q-67-48-30-50L43-39Q67-35 66-11L58 44-51 44Z" fill="${baked}" stroke="#be935e" stroke-width="3"/><path d="M-64-21Q-68-47-30-49L43-38Q64-35 65-13Q52-3 44-12Q34-19 29-3Q20 14 12-4Q-2-19-12-6Q-21 4-31-11Q-48-16-64-9Z" fill="${frost?pink:'#faf0c9'}"/><circle cx="18" cy="-30" r="16" fill="#f6d367" stroke="#ffec9f" stroke-width="4"/><path d="M18-44v28M5-30h27M8-40l21 21" stroke="#ffefb7" stroke-width="2"/>`}else{inner=`<ellipse cy="55" rx="69" ry="16" fill="#e2d2cc"/><path d="M-61-16H61V48Q0 75-61 48Z" fill="${baked}" stroke="#c59078" stroke-width="3"/><path d="M-61 12Q0 32 61 12v13Q0 44-61 25Z" fill="#f5d0d7"/><ellipse cy="-17" rx="61" ry="20" fill="${pink}" stroke="#d5b2b0" stroke-width="3"/><path d="M-61-17v18q8 16 17 0v-6q12 15 22 0q14 20 25 0q12 17 23 0q15 18 24 0v-12" fill="${pink}"/>${[-30,0,30].map(x=>`<path d="M${x-10}-32q10-23 20 0q-10 24-20 0" fill="#df8593"/><path d="M${x-5}-44l5 8 6-7" stroke="#82986b" stroke-width="4" fill="none"/>`).join('')}`}
const dense=quality<.8&&r.id!=='cookie'; const drizzle=frost&&['cookie','brownie'].includes(r.id)?`<path d="M-45-15q20-15 15 0t20 0t20 0t20 0M-40 5q20-15 15 0t20 0t20 0" fill="none" stroke="${pink}" stroke-width="6" stroke-linecap="round"/>`:'';return `<svg viewBox="-100 -90 200 180" role="img" aria-label="${esc(r.name)}"><ellipse cy="70" rx="80" ry="12" fill="#fff9f1" opacity=".8"/>${dense?'<g transform="translate(0 22) scale(1 .65)">':'<g>'}${inner}${drizzle}</g><g fill="#674b42"><circle cx="-9" cy="${r.id==='cookie'?25:30}" r="2.5"/><circle cx="9" cy="${r.id==='cookie'?25:30}" r="2.5"/></g><path d="M-4 ${r.id==='cookie'?31:36}q4 5 8 0" fill="none" stroke="#674b42" stroke-width="2" stroke-linecap="round"/></svg>`}
function clearTimers(){clearInterval(timer);clearTimeout(mixTimer);timer=null}
function book(){clearTimers();state=null;app.innerHTML=`<section class="intro"><span class="tag">A cozy little baking game</span><h1>A pinch of joy.<br>A spoonful of <em>magic.</em></h1><p>Tie your apron, pick a recipe, and bake someone’s day.<br>Every little choice makes your creation uniquely yours.</p></section><div class="sectionbar"><h2>What shall we bake today?</h2><span>5 recipes · a little something for every baker</span></div><section class="recipes">${recipes.map((r,i)=>`<button class="recipe" data-recipe="${i}" aria-label="Bake ${r.name}"><div class="art" style="--bg:${r.color}">${art(r,1,r.frost)}</div><div class="recipebody"><div class="difficulty">${'✿'.repeat(i+1)} · ${r.level}</div><h3>${r.name}</h3><p>${r.desc}</p><div class="recipebottom"><span>◷ ${r.time} min bake</span><b>↗</b></div></div></button>`).join('')}</section><aside class="note"><span>♡</span><div><strong>A little messy is part of the magic.</strong>Measure, mix, bake, and decorate. Happy accidents are welcome—your customer will tell you how it tastes!</div></aside>`;app.querySelectorAll('[data-recipe]').forEach(b=>b.onclick=()=>start(+b.dataset.recipe))}
function start(i){clearTimers();state={r:recipes[i],stage:0,amounts:{},mix:0,temp:175,minutes:20,bakeProgress:0,baking:false,baked:false,frost:null,top:null,decor:[]};render()}
function side(){const r=state.r;return `<aside class="paper"><div class="eyebrow">From the recipe book</div><h2>${r.name}</h2><div class="difficulty">${r.level}</div><p>One small batch · baked with love</p><strong class="subtle">DRY INGREDIENTS</strong><div class="booklist">${r.dry.map(([n,v,u])=>`<div><span>${n}</span><b>${quantity(n,v,u)}</b></div>`).join('')}</div><p></p><strong class="subtle">WET INGREDIENTS</strong><div class="booklist">${r.wet.map(([n,v,u])=>`<div><span>${n}</span><b>${quantity(n,v,u)}</b></div>`).join('')}</div><p>Mix until silky & smooth<br>Bake: ${r.temp}°C for ${r.time} min</p><div class="customer"><b>♡ ${r.customer}’s order</b><p>“${r.wish}”</p></div></aside>`}
function render(){const s=state,r=s.r;app.innerHTML=`<nav class="steps" aria-label="Baking progress">${stages.map((x,i)=>`<span class="step ${i===s.stage?'active':i<s.stage?'done':''}">${i<s.stage?'✓':String(i+1).padStart(2,'0')} ${x}</span>`).join('')}</nav><div class="studio">${side()}<section class="workspace" id="work"></section></div>`;if(s.stage<2)ingredientStage();if(s.stage===2)mixStage();if(s.stage===3)bakeStage();if(s.stage===4)decorateStage()}
function fraction(v){const whole=Math.floor(v),rest=Math.round((v-whole)*4);return (whole||'')+(['','¼','½','¾'][rest]||'')||'0'}
function quantity(n,v,u){let amount=v,unit=u;if(u==='¼ cup'){amount=v/4;unit='cup'}if(u==='½ tsp'){amount=v/2;unit='tsp'}if(u==='¼ tsp'){amount=v/4;unit='tsp'}if(unit==='egg'||unit==='pinch'){return fraction(amount)+' '+(amount===1?unit:unit==='egg'?'eggs':'pinches')}return fraction(amount)+' '+unit+(unit==='cup'&&(amount>1||amount===0)?'s':'')}
function ingredientArt(name){const colors={'Flour':'#f4dfb5','Sugar':'#efc8d6','Baking soda':'#b9d8c6','Baking powder':'#cfc5e4','Chocolate chips':'#cba48e','Cocoa':'#b68a70','Salt':'#c0d5df'};const face='<circle cx="44" cy="72" r="2"/><circle cx="57" cy="72" r="2"/><path d="M47 79q4 4 7 0" fill="none" stroke="#705349" stroke-width="2" stroke-linecap="round"/>';let shape='';if(name==='Egg'){shape='<ellipse cx="50" cy="60" rx="27" ry="36" fill="#f5dfbd"/><path d="M32 56q0-15 9-20" stroke="#fff5df" stroke-width="6" fill="none" stroke-linecap="round"/>'}else if(name==='Butter'){shape='<path d="M14 49l21-17 51 11-1 35-23 17-48-14z" fill="#ffeda9"/><path d="M14 49l48 14 24-20-51-11z" fill="#fff5cc"/><path d="M62 63v32l23-17V43z" fill="#e8c879"/><path d="M27 46l18-10M45 51l18-11" stroke="#e7cf8a" stroke-width="2"/>'}else if(['Milk','Vanilla','Lemon juice'].includes(name)){const milk=name==='Milk';shape=`<path d="M31 17h38v17l9 12v52H22V46l9-12z" fill="${milk?'#fff9ed':name==='Vanilla'?'#b78b6d':'#eed78c'}"/><path d="M31 17h38v14H31z" fill="${milk?'#acd0df':name==='Vanilla'?'#a6c3a0':'#c4d296'}"/><rect x="25" y="49" width="50" height="40" rx="8" fill="${milk?'#c5deea':'#fff0d0'}"/><text x="50" y="61" font-size="8" text-anchor="middle" fill="#705349">${milk?'MILK':name==='Vanilla'?'VANILLA':'LEMON'}</text>`}else{const color=colors[name]||'#e7c9ac';shape=`<path d="M24 20h52l-5 14 9 16 3 48H17l3-48 9-16z" fill="${color}"/><path d="M24 20h52M29 34h42" stroke="#fff5e5" stroke-width="5"/><rect x="25" y="49" width="50" height="40" rx="9" fill="#fffaf0"/><text x="50" y="61" font-size="${name.length>10?6:8}" font-weight="700" text-anchor="middle" fill="#705349">${name.toUpperCase()}</text>`}return `<svg viewBox="0 0 100 110" role="img" aria-label="${esc(name)}"><ellipse cx="50" cy="102" rx="33" ry="5" fill="#a77e6318"/><g stroke="#82614e" stroke-width="2" stroke-linejoin="round">${shape}</g><g fill="#705349">${face}</g><ellipse cx="35" cy="79" rx="4" ry="2" fill="#e9a5ac88"/><ellipse cx="66" cy="79" rx="4" ry="2" fill="#e9a5ac88"/></svg>`}
function bowlArt(mixing=false){return `<svg viewBox="0 0 360 270" aria-hidden="true"><ellipse cx="180" cy="235" rx="130" ry="16" fill="#8d68501c"/><path d="M39 107q4 125 141 126q136-2 141-126z" fill="#b5cbdc" stroke="#748fa8" stroke-width="4"/><path d="M67 130q10 58 43 75" fill="none" stroke="#d9e5ec" stroke-width="10" stroke-linecap="round"/><ellipse cx="180" cy="107" rx="141" ry="49" fill="#e5eff4" stroke="#748fa8" stroke-width="4"/><ellipse cx="180" cy="107" rx="124" ry="35" fill="${mixing?'#e4bf8f':'#efe2c6'}" class="batter"/><g class="batterSwirl" transform="rotate(0 180 107)" fill="none" stroke="${mixing?'#d4a575':'#fff8df'}" stroke-width="5" stroke-linecap="round"><path d="M104 105q18-31 82-23q65 9 35 31q-35 21-71 0q-13-13 27-14q29 1 15 9"/></g><g fill="#6d7187"><circle cx="159" cy="182" r="4"/><circle cx="201" cy="182" r="4"/></g><path d="M172 194q8 8 16 0" stroke="#6d7187" stroke-width="3" fill="none" stroke-linecap="round"/><ellipse cx="144" cy="193" rx="9" ry="4" fill="#e9b1c0"/><ellipse cx="217" cy="193" rx="9" ry="4" fill="#e9b1c0"/></svg>`}
function ingredientStage(){const s=state,items=s.stage===0?s.r.dry:s.r.wet;s.portions??={};s.history??=[];s.selected=null;document.getElementById('work').innerHTML=`<div class="eyebrow">Step ${s.stage+1} · Your little kitchen</div><h2>${s.stage===0?'Let’s make a little magic.':'Time for a splash & a crack.'}</h2><p>Pick a measure, then drag an ingredient into the bowl. Drop it over the bowl and watch it pour. Eggs crack right into the batter!</p><div class="kitchen-scene"><div class="pantry">${items.map(([n,v,u],i)=>{let portions=u==='¼ cup'?[1,2,4]:u==='½ tsp'?[1,2]:u==='¼ tsp'?[1,2,4]:[1];portions=n==='Egg'?[1]:[...new Set([...portions,v])].sort((a,b)=>a-b);s.portions[n]??=n==='Egg'?1:v;return `<div class="pantry-item"><button class="ingredient-packet" data-ingredient="${i}" aria-label="Pick up ${n}">${ingredientArt(n)}<strong>${n}</strong></button><select aria-label="Measure ${n}" data-measure="${i}">${portions.map(p=>`<option value="${p}" ${s.portions[n]===p?'selected':''}>${quantity(n,p,u)}</option>`).join('')}</select><span class="added" id="added${i}">${quantity(n,s.amounts[n]||0,u)} added</span></div>`}).join('')}</div><div class="bowl-station"><span class="scene-note">a pinch of patience, a spoonful of joy</span><button class="drop-bowl" id="dropBowl" aria-label="Mixing bowl. Drop or tap to add selected ingredient.">${bowlArt()}<span id="bowlHint">Drop ingredients here ↓</span></button><div class="ingredient-chips" id="bowlContents"></div><div class="toast" id="pourNote" role="status">Your bowl is ready.</div><button class="quiet small" id="undoPour">↶ Undo last pour</button></div></div><button class="primary" id="next">${s.stage===0?'Next: wet ingredients →':'Let’s mix →'}</button><p class="subtle">It’s okay to experiment. Your final bake remembers your choices.</p>`;
const bowl=document.getElementById('dropBowl');function updateContents(){document.getElementById('bowlContents').innerHTML=items.filter(([n])=>s.amounts[n]>0).map(([n,v,u])=>`<span>${n} · ${quantity(n,s.amounts[n],u)}</span>`).join('')}updateContents();
function add(i){if(i===null||s.pouring)return;const [n,,u]=items[i],amount=s.portions[n];s.pouring=true;animateIngredient(n,amount,u,()=>{if(state!==s)return;s.pouring=false;s.amounts[n]=Math.min(40,(s.amounts[n]||0)+amount);s.history.push({n,amount,stage:s.stage});document.getElementById('added'+i).textContent=quantity(n,s.amounts[n],u)+' added';document.getElementById('pourNote').textContent=`${quantity(n,amount,u)} ${n.toLowerCase()} tumbled into the bowl!`;bowl.classList.remove('pouring');void bowl.offsetWidth;bowl.classList.add('pouring');updateContents();let puff=document.createElement('span');puff.className='pour-puff';puff.textContent=n==='Egg'?'✦':'✧';bowl.appendChild(puff);setTimeout(()=>puff.remove(),650)},()=>{s.pouring=false})}
document.querySelectorAll('[data-measure]').forEach(el=>el.onchange=()=>{s.portions[items[+el.dataset.measure][0]]=+el.value});
document.querySelectorAll('[data-ingredient]').forEach(el=>{const i=+el.dataset.ingredient;el.onclick=()=>{s.selected=i;document.querySelectorAll('.ingredient-packet').forEach(b=>b.classList.toggle('picked',b===el));document.getElementById('bowlHint').textContent=`Tap the bowl to add ${items[i][0].toLowerCase()}`};bindDrag(el,()=>ingredientArt(items[i][0]),(x,y)=>{const r=bowl.getBoundingClientRect();if(x>=r.left&&x<=r.right&&y>=r.top&&y<=r.bottom){add(i)}else{document.getElementById('pourNote').textContent='Bring it over the bowl and let go!'}},(x,y)=>{const r=bowl.getBoundingClientRect();bowl.classList.toggle('drop-ready',x>=r.left&&x<=r.right&&y>=r.top&&y<=r.bottom)})});
bowl.onclick=()=>{if(s.selected===null){document.getElementById('pourNote').textContent='Pick an ingredient from the pantry first.';return}add(s.selected)};document.getElementById('undoPour').onclick=()=>{const last=s.history.at(-1);if(!last||last.stage!==s.stage)return;s.history.pop();s.amounts[last.n]=Math.max(0,(s.amounts[last.n]||0)-last.amount);const i=items.findIndex(x=>x[0]===last.n);document.getElementById('added'+i).textContent=quantity(last.n,s.amounts[last.n],items[i][2])+' added';document.getElementById('pourNote').textContent='Last pour scooped back out.';updateContents()};document.getElementById('next').onclick=()=>{s.stage++;render()}}
function bindDrag(el,html,onDrop,onMove=()=>{}){let drag=null,ghost=null,blocked=false;el.style.touchAction='none';el.addEventListener('pointerdown',e=>{if(e.button!==0)return;drag={id:e.pointerId,x:e.clientX,y:e.clientY,moved:false};el.setPointerCapture(e.pointerId)});el.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;if(!drag.moved&&Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>7){drag.moved=true;ghost=document.createElement('div');ghost.className='drag-ghost';ghost.innerHTML=html();document.body.appendChild(ghost);el.classList.add('dragging')}if(drag.moved){e.preventDefault();ghost.style.left=e.clientX+'px';ghost.style.top=e.clientY+'px';onMove(e.clientX,e.clientY)}});function cleanup(){ghost?.remove();ghost=null;el.classList.remove('dragging');document.querySelectorAll('.drop-ready').forEach(x=>x.classList.remove('drop-ready'));drag=null}el.addEventListener('pointerup',e=>{if(!drag)return;const moved=drag.moved;if(moved){blocked=true;onDrop(e.clientX,e.clientY);setTimeout(()=>blocked=false,0)}cleanup()});el.addEventListener('pointercancel',cleanup);el.addEventListener('click',e=>{if(blocked){e.stopImmediatePropagation();e.preventDefault()}},true)}
function mixStage(){const s=state;document.getElementById('work').innerHTML=`<div class="eyebrow">Step 3 · Stir it up!</div><h2>A little swirl, a little magic.</h2><p>Grab the whisk and stir in circles inside the bowl. The batter will turn silky—stop when you see “Just right!”</p><div class="mix-station mama-mix" id="mixArea" tabindex="0" role="application" aria-label="Stir the bowl in circles, or use the left and right arrow keys.">${bowlArt(true)}<svg class="whisk" id="whisk" viewBox="0 0 100 160" aria-hidden="true"><path d="M50 3v65" stroke="#b48ba1" stroke-width="14" stroke-linecap="round"/><path d="M47 9v48" stroke="#e7cfdd" stroke-width="4" stroke-linecap="round"/><g fill="none" stroke="#869da9" stroke-width="3"><ellipse cx="50" cy="107" rx="24" ry="43"/><ellipse cx="50" cy="107" rx="12" ry="43"/><path d="M50 64v86"/></g></svg><span class="swirl-guide">↻</span><div class="batter-dots">${Array.from({length:7},(_,i)=>`<i style="--x:${35+i*7%30}%;--y:${35+i*2%8}%"></i>`).join('')}</div></div><div class="mix-status" id="mixStatus" role="status">Grab your whisk!</div><div class="meter mix-meter"><div class="zone" style="left:44%;width:12%"></div><div class="fill" id="mixfill" style="width:0"></div></div><button class="primary" id="next">Into the oven →</button><p class="subtle">Touch: draw circles with one finger. Keyboard: ← or →.</p>`;
const area=document.getElementById('mixArea'),whisk=document.getElementById('whisk');let dragging=false,lastAngle=null,rotation=0,turn=0;const goalTurns=Math.max(3,Math.round(s.r.mix/2));function center(){const r=area.getBoundingClientRect();return {r,x:r.left+r.width*.5,y:r.top+r.height*.395}}function setWhisk(x,y){const {r}=center();whisk.style.left=(x-r.left)+'px';whisk.style.top=(y-r.top)+'px'}function update(){const f=s.mix/s.r.mix;document.getElementById('mixfill').style.width=Math.min(100,f*50)+'%';document.getElementById('mixStatus').textContent=f<.65?'Keep stirring!':f<.88?'Almost silky…':f<=1.12?'Just right! Lovely and smooth.':'A little too much stirring!';area.classList.toggle('smooth',f>=.88);area.style.setProperty('--lump-opacity',Math.max(0,1-f));area.querySelector('.batterSwirl').setAttribute('transform',`rotate(${rotation} 180 107)`);area.querySelector('.batter').style.fill=f<.88?'#e4c594':'#e7bd86'}
function pointer(e){const c=center(),dx=e.clientX-c.x,dy=(e.clientY-c.y)*1.7;return {c,dx,dy,radius:Math.hypot(dx,dy),a:Math.atan2(dy,dx)}}function moveWhisk(e){const p=pointer(e),radius=Math.min(p.c.r.width*.31,p.radius);setWhisk(p.c.x+Math.cos(p.a)*radius,p.c.y+Math.sin(p.a)*radius/1.7);return p}
area.onpointerdown=e=>{if(e.button!==0)return;const p=pointer(e);dragging=true;area.setPointerCapture(e.pointerId);lastAngle=p.radius>15?p.a:null;moveWhisk(e);area.classList.add('mixing');e.preventDefault()};area.onpointermove=e=>{if(!dragging)return;const p=moveWhisk(e);if(p.radius<15){lastAngle=null;return}if(lastAngle!==null){let d=p.a-lastAngle;while(d>Math.PI)d-=Math.PI*2;while(d< -Math.PI)d+=Math.PI*2;if(Math.abs(d)<1.6){rotation+=d*180/Math.PI;s.mix+=Math.abs(d)/(Math.PI*2)*s.r.mix/goalTurns;update()}}lastAngle=p.a};area.onpointerup=area.onpointercancel=()=>{dragging=false;lastAngle=null;area.classList.remove('mixing')};area.onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();s.mix+=s.r.mix/(goalTurns*4);rotation+=90;const c=center();setWhisk(c.x+Math.cos(rotation*Math.PI/180)*70,c.y+Math.sin(rotation*Math.PI/180)*40);update()}};document.getElementById('next').onclick=()=>{s.stage++;render()};const r=area.getBoundingClientRect();setWhisk(r.left+r.width*.56,r.top+r.height*.39);update()}

function ovenArt(){return `<div class="illustrated-oven" id="ovenDrop"><div class="oven-top"><span>✿ BUTTERCUP</span><i></i><i></i><i></i></div><div class="oven-handle"></div><div class="oven-window">${state.baking||state.baked?`<div class="oven-bake"><div class="inoven-food">${ovenRackBake()}</div></div>`:'<div class="oven-shelf"></div>'}</div><div class="oven-feet"></div><span class="oven-drop-label">${state.baking?'Baking something lovely…':state.baked?'Ding! Freshly baked.':'Slide your tray into the oven'}</span></div>`}
function bakeStage(){const s=state;document.getElementById('work').innerHTML=`<div class="eyebrow">Step 4 · Warm & wonderful</div><h2>${s.baked?'Ding! A little golden happiness.':'Into the cozy oven.'}</h2><p>${s.baked?'Your bake is cooling. Let’s give it a little personality!':'Turn the sliders to set your oven, then drag the tray into the oven. Pull it out early if you wish—your bake will remember.'}</p><div class="oven-scene">${ovenArt()}${!s.baking&&!s.baked?`<button class="baking-tray" id="tray" aria-label="Pick up baking tray">${typeof panArt==='function'&&s.pan?flowArt(s):`<svg viewBox="0 0 210 105" aria-hidden="true"><path d="M16 21h178l10 70H6z" fill="#bcc6cb" stroke="#84919b" stroke-width="4"/><path d="M25 30h160l6 50H18z" fill="#e6d7bf"/>${[45,105,165].map(x=>`<ellipse cx="${x}" cy="56" rx="22" ry="16" fill="#d9b88b"/>`).join('')}</svg>`}<span>Drag me into the oven ↗</span></button>`:''}</div><div class="controls oven-controls"><label>Temperature · <output id="tempValue">${s.temp}°C</output><input id="temp" type="range" aria-label="Oven temperature" min="100" max="250" step="5" value="${s.temp}" ${s.baking||s.baked?'disabled':''}></label><label>Timer · <output id="minutesValue">${s.minutes} min</output><input id="minutes" type="range" aria-label="Oven timer" min="1" max="60" value="${s.minutes}" ${s.baking||s.baked?'disabled':''}></label></div><div class="meter"><div class="fill" id="bakefill" style="width:${s.bakeProgress/s.minutes*100}%"></div></div><div class="readout" id="elapsed">${s.bakeProgress.toFixed(1)} / ${s.minutes} min</div><button class="primary" id="ovenBtn">${s.baked?'Time to decorate →':s.baking?'Take it out now':'Place tray in oven'}</button><div class="toast" id="ovenNote" role="status">${s.baked?'The kitchen smells wonderful.':''}</div>`;
for(const id of ['temp','minutes'])document.getElementById(id).oninput=e=>{s[id]=+e.target.value;document.getElementById(id+'Value').textContent=s[id]+(id==='temp'?'°C':' min')};function begin(){s.baking=true;render();timer=setInterval(()=>{s.bakeProgress=Math.min(s.minutes,s.bakeProgress+.5);document.getElementById('bakefill').style.width=s.bakeProgress/s.minutes*100+'%';document.getElementById('elapsed').textContent=s.bakeProgress.toFixed(1)+' / '+s.minutes+' min';if(typeof refreshOvenAppearance==='function')refreshOvenAppearance();if(s.bakeProgress>=s.minutes)finishBake()},160)}
if(!s.baking&&!s.baked){const tray=document.getElementById('tray'),oven=document.getElementById('ovenDrop');bindDrag(tray,()=>tray.querySelector('svg').outerHTML,(x,y)=>{const r=oven.getBoundingClientRect();if(x>=r.left&&x<=r.right&&y>=r.top&&y<=r.bottom)begin();else document.getElementById('ovenNote').textContent='Bring the tray over the oven window.'},(x,y)=>{const r=oven.getBoundingClientRect();oven.classList.toggle('drop-ready',x>=r.left&&x<=r.right&&y>=r.top&&y<=r.bottom)})}
document.getElementById('ovenBtn').onclick=()=>{if(s.baked){s.stage++;render()}else if(s.baking)finishBake();else begin()}}
function finishBake(){clearInterval(timer);timer=null;state.baking=false;state.baked=true;render()}
const toppingEmoji={'Sprinkles':'✨','Strawberries':'🍓','Chocolate chips':'🍫','Flowers':'🌸'};
function toppingArt(t){let shapes='';if(t==='Strawberries')shapes='<path d="M20 40Q50 5 80 40Q80 68 50 91Q20 68 20 40" fill="#e78f9d" stroke="#be6379" stroke-width="3"/><path d="M28 31l14-11 8 13 10-13 13 12-23 6Z" fill="#9db784"/><g fill="#fff1b3"><ellipse cx="37" cy="47" rx="2" ry="3"/><ellipse cx="60" cy="49" rx="2" ry="3"/><ellipse cx="48" cy="65" rx="2" ry="3"/><ellipse cx="63" cy="64" rx="2" ry="3"/></g>';else if(t==='Flowers')shapes='<g fill="#ebbad2" stroke="#c28ea9" stroke-width="2"><ellipse cx="50" cy="32" rx="14" ry="20"/><ellipse cx="50" cy="70" rx="14" ry="20"/><ellipse cx="30" cy="50" rx="20" ry="14"/><ellipse cx="70" cy="50" rx="20" ry="14"/></g><circle cx="50" cy="50" r="13" fill="#f4d68a"/>';else if(t==='Chocolate chips')shapes='<path d="M21 72Q21 53 42 45Q53 37 54 17Q73 36 80 62Q87 86 54 88Q26 89 21 72" fill="#8a604f" stroke="#634638" stroke-width="3"/><path d="M36 67q4-12 16-16" fill="none" stroke="#b88b73" stroke-width="5" stroke-linecap="round"/>';else shapes=[[25,26,'#dc9db4'],[60,20,'#aec6d3'],[42,50,'#e5bc63'],[72,60,'#aaadcc'],[23,75,'#b7c898']].map(([x,y,c])=>`<path d="M${x} ${y}l10 13" stroke="${c}" stroke-width="8" stroke-linecap="round"/>`).join('');return `<svg viewBox="0 0 100 100" role="img" aria-label="${t}">${shapes}</svg>`}
function pipingArt(t){const color=icingColor(t);return `<svg viewBox="0 0 100 120" role="img" aria-label="${t} piping bag"><path d="M25 14l53 4-20 71-22 4Z" fill="${color}" stroke="#b49394" stroke-width="2"/><path d="M36 93l22-4-11 26z" fill="#b1bac3" stroke="#81919c" stroke-width="2"/><path d="M24 13l-4-9 20 4 15-5 25 4-3 12" fill="${color}" stroke="#b49394" stroke-width="2"/><path d="M35 30l9 39" stroke="#fff9" stroke-width="6" stroke-linecap="round"/></svg>`}
function icingColor(t){return t==='Chocolate'?'#8d6251':t==='Lemon glaze'?'#f7dfa0':t==='Vanilla'?'#fff5dd':'#edb2c8'}
function plate(){return `<div class="plate" id="plate" tabindex="0" role="button" aria-label="Your bake. Drop decorations here, or select a tool and press Enter.">${art(state.r,scoreBake().quality,state.frost)}${(state.icing||[]).map(d=>`<span class="icing-dot" style="left:${d.x}%;top:${d.y}%;--icing:${icingColor(d.type)}"></span>`).join('')}${state.decor.map(d=>`<span class="sprinkle" style="left:${d.x}%;top:${d.y}%">${toppingArt(d.type)}</span>`).join('')}</div>`}
function decorateStage(){const s=state;s.icing??=[];s.tool??=null;document.getElementById('work').innerHTML=`<div class="eyebrow">Step 5 · Your sweet little canvas</div><h2>A swirl, a berry, a little love.</h2><p>Drag a piping bag or topping onto your bake. Select a piping bag, then hold & draw on the bake to pipe frosting. Tap-to-place works too!</p><div class="decorating-table"><div class="tool-tray"><span class="eyebrow">Piping bags</span>${['Strawberry','Vanilla','Chocolate','Lemon glaze'].map(t=>`<button class="decor-tool ${s.tool?.type===t?'selected':''}" data-frost="${t}" aria-label="${t} piping bag">${pipingArt(t)}<span>${t}</span></button>`).join('')}</div><div>${plate()}<div class="toast" id="decorNote" role="status">${s.tool?'Selected: '+s.tool.type:'Choose a little something from the decorating tray.'}</div></div><div class="tool-tray"><span class="eyebrow">Toppings</span>${Object.keys(toppingEmoji).map(t=>`<button class="decor-tool ${s.tool?.type===t?'selected':''}" data-top="${t}" aria-label="${t} topping">${toppingArt(t)}<span>${t}</span></button>`).join('')}</div></div><button class="quiet small" id="clear">↶ Clear decorations</button><br><button class="primary" id="serve">Serve with love ♡</button>`;
const cake=document.getElementById('plate');function place(kind,type,x,y){const r=cake.getBoundingClientRect();if(x<r.left||x>r.right||y<r.top||y>r.bottom)return;const dot={type,x:Math.max(5,Math.min(90,(x-r.left)/r.width*100-4)),y:Math.max(5,Math.min(82,(y-r.top)/r.height*100-4))};if(kind==='frost'){s.frost=type;if(s.icing.length>=100)return;s.icing.push(dot);const el=document.createElement('span');el.className='icing-dot';el.style.cssText=`left:${dot.x}%;top:${dot.y}%;--icing:${icingColor(type)}`;cake.appendChild(el);cake.querySelector('svg').outerHTML=art(s.r,scoreBake().quality,s.frost)}else{if(s.decor.length>=30)return;s.decor.push(dot);const el=document.createElement('span');el.className='sprinkle';el.style.cssText=`left:${dot.x}%;top:${dot.y}%`;el.innerHTML=toppingArt(type);cake.appendChild(el)}document.getElementById('decorNote').textContent='Looking lovely! Keep decorating or serve with love.'}
for(const kind of ['frost','top'])document.querySelectorAll('[data-'+kind+']').forEach(el=>{const type=el.dataset[kind];el.onclick=()=>{s.tool={kind,type};document.querySelectorAll('.decor-tool').forEach(b=>b.classList.toggle('selected',b===el));document.getElementById('decorNote').textContent=kind==='frost'?type+' selected. Hold and draw on your bake.':type+' selected. Tap your bake to place.'};bindDrag(el,()=>kind==='frost'?pipingArt(type):toppingArt(type),(x,y)=>{s.tool={kind,type};place(kind,type,x,y);document.querySelectorAll('.decor-tool').forEach(b=>b.classList.toggle('selected',b===el))},(x,y)=>{const r=cake.getBoundingClientRect();cake.classList.toggle('drop-ready',x>=r.left&&x<=r.right&&y>=r.top&&y<=r.bottom)})});let drawing=false,last=null;cake.onpointerdown=e=>{if(e.button!==0||!s.tool)return;drawing=true;cake.setPointerCapture(e.pointerId);place(s.tool.kind,s.tool.type,e.clientX,e.clientY);last={x:e.clientX,y:e.clientY};e.preventDefault()};cake.onpointermove=e=>{if(!drawing||s.tool?.kind!=='frost')return;if(Math.hypot(e.clientX-last.x,e.clientY-last.y)>12){place('frost',s.tool.type,e.clientX,e.clientY);last={x:e.clientX,y:e.clientY}}};cake.onpointerup=cake.onpointercancel=()=>drawing=false;cake.onkeydown=e=>{if((e.key==='Enter'||e.key===' ')&&s.tool){e.preventDefault();const r=cake.getBoundingClientRect();const count=s.decor.length+s.icing.length;place(s.tool.kind,s.tool.type,r.left+r.width*(.25+(count*17%50)/100),r.top+r.height*(.25+(count*11%45)/100))}};document.getElementById('clear').onclick=()=>{s.decor=[];s.icing=[];s.frost=null;decorateStage()};document.getElementById('serve').onclick=results}
function scoreBake(){const s=state,r=s.r;let penalty=0,notes=[];const amount=n=>s.amounts[n]||0,target=n=>[...r.dry,...r.wet].find(x=>x[0]===n)?.[1]||0;const ratio=n=>target(n)?amount(n)/target(n):1;for(const [n,v]of [...r.dry,...r.wet])penalty+=Math.min(1.5,Math.abs(amount(n)-v)/v)*6;
const lift=r.dry.find(x=>/Baking/.test(x[0]));if(lift&&ratio(lift[0])<.8)notes.push(['Texture',`Too little ${lift[0].toLowerCase()} made your bake dense and less fluffy.`]);if(lift&&ratio(lift[0])>1.2)notes.push(['Texture',`Extra ${lift[0].toLowerCase()} left a bitter aftertaste and an uneven rise.`]);if(ratio('Flour')>1.2)notes.push(['Crumb','Extra flour made the crumb dry and heavy.']);if(ratio('Flour')<.8)notes.push(['Structure','Too little flour left a weak, fragile structure.']);if(ratio('Sugar')<.8)notes.push(['Sweetness','Less sugar made this bake less sweet than the customer expected.']);if(ratio('Sugar')>1.2)notes.push(['Sweetness','A little too much sugar made this bake overly sweet.']);if(ratio('Butter')<.8||ratio('Egg')<.8)notes.push(['Richness','Missing butter or egg left the bake less tender and rich.']);if(ratio('Butter')>1.3||ratio('Egg')>1.3)notes.push(['Balance','Extra butter or egg made the texture heavier than intended.']);for(const [n]of [...r.dry,...r.wet].filter(x=>!['Flour','Sugar','Butter','Egg'].includes(x[0])&&!/Baking/.test(x[0]))){if(ratio(n)<.8||ratio(n)>1.2)notes.push(['Recipe balance',`${n} was ${ratio(n)<1?'under':'over'} the recipe amount, changing the flavor or moisture.`])}
const mixError=Math.abs(s.mix-r.mix)/r.mix;penalty+=Math.min(25,mixError*24);if(mixError>.2)notes.push(['Mixing',s.mix<r.mix?'Not enough mixing left uneven pockets and lumps.':'Too much mixing made the crumb tougher.']);const heat=s.bakeProgress/r.time*Math.pow(s.temp/r.temp,2);penalty+=Math.min(40,Math.abs(1-heat)*55);if(heat<.85)notes.push(['Oven','The bake came out too early or too cool, leaving an underbaked center.']);else if(heat>1.15)notes.push(['Oven','Too much oven heat dried out the edges and browned them too far.']);if(Math.abs(s.temp-r.temp)>20){penalty+=10;notes.push(['Temperature','The oven temperature was far from the recipe, so the bake cooked unevenly.'])}return {quality:Math.max(0,1-penalty/100),notes,penalty}}
function results(){clearTimers();const s=state,r=s.r,result=scoreBake(),correctFrost=s.frost===r.frost,correctTop=s.decor.some(x=>x.type===r.top);let points=Math.max(0,100-result.penalty-(correctFrost?0:10)-(correctTop?0:10));const stars=Math.max(1,Math.min(5,(points>=97?5:points>=80?4:points>=60?3:points>=35?2:1))),notes=[...result.notes];notes.push(['Decoration',correctFrost&&correctTop?'You matched the customer’s frosting and topping wishes. A lovely finishing touch!':`The customer asked for ${r.frost.toLowerCase()} and ${r.top.toLowerCase()}. ${!correctFrost?'Try matching the frosting. ':''}${!correctTop?'Remember to place their favorite topping on the bake.':''}`]);if(result.notes.length===0)notes.unshift(['Beautifully baked','Lovely balance, just the right mixing, and a perfect bake. Your recipe care really shows!']);app.innerHTML=`<section class="result"><div class="eyebrow">Fresh from your little bakery</div><h1>${stars>=4?'Sweet success!':stars===3?'A lovely little learning bake.':'Every baker starts somewhere.'}</h1><p>${r.customer} has tried your ${r.name.toLowerCase()}.</p>${plate()}<div class="stars" aria-label="${stars} out of 5 stars">${'★'.repeat(stars)}${'☆'.repeat(5-stars)}</div><p>“${stars===5?'Oh, this is dreamy! I’ll be back for another.':stars===4?'So yummy! Just a tiny bit of room for more magic.':stars===3?'Made with love, but the recipe could use a little more care.':'A brave first bake! Let’s check the recipe and try again.'}”</p><div class="feedback">${notes.map(([title,text])=>`<div><strong>${title}</strong><br>${text}</div>`).join('')}</div><div class="actions"><button class="quiet" id="again">Bake this again</button><button class="primary" id="choose" style="margin:0">Another recipe →</button></div><p class="subtle">A playful baking simulation. These recipes and ratings are for the game.</p></section>`;document.getElementById('again').onclick=()=>start(recipes.indexOf(r));document.getElementById('choose').onclick=book}
document.getElementById('bookBtn').onclick=()=>{if(!state){book();return}const r=state.r,dialog=document.createElement('dialog');dialog.innerHTML=`<h2>Your recipe book</h2><p>You’re baking ${r.name.toLowerCase()}. Your recipe card stays beside your workstation.</p><button class="primary" id="resume">Keep baking</button> <button class="quiet" id="leave">Choose another recipe</button><p class="subtle">Choosing another recipe starts a fresh bake.</p>`;document.body.appendChild(dialog);dialog.showModal();dialog.querySelector('#resume').onclick=()=>dialog.close();dialog.querySelector('#leave').onclick=()=>{dialog.close();book()};dialog.onclose=()=>dialog.remove()};book();
